"""Build two real routes for the source-backed helmet editions."""
import json,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];PUBLIC=ROOT/'public'
editions=[
 {'id':'season-2023','title':'SEASON<br>2023','name':'Season 2023','zh':'2023 赛季常规款','year':'2023','eyebrow':'THE SEASON DESIGN','poster':'/max/helmet-04-02.jpg','photos':['/max/helmet-04-02.jpg','/max/helmet-04-00.jpg','/max/helmet-04-01.jpg','/max/helmet-04-03.jpg'],'story':'WHITE. RED. BLUE.','body':'The season design, from the crown to the chin. Explore the lines, the visor and the details from every angle.','bodyZh':'从盔顶到下颌，近看常规款的线条、镜片与涂装细节。','source':'https://www.redbullshop.com/en-int/p/RBR23248/'},
 {'id':'zandvoort-2024','title':'ORANGE<br>TRIBUTE','name':'Zandvoort 2024','zh':'2024 荷兰站 · 橙色致敬','year':'2024','eyebrow':'ZANDVOORT / THE NETHERLANDS','poster':'/max/orange-2024-04.jpg','photos':['/max/orange-2024-03.jpg','/max/orange-2024-04.jpg','/max/orange-2024-05.jpg','/max/orange-2024-06.jpg','/max/orange-2024-07.jpg','/max/orange-2024-08.jpg'],'story':'FOR THE<br>ORANGE ARMY.','body':'An Orange Tribute to the fans. Bright orange, white lines and the crowd woven into the design: the 2024 European special worn at Zandvoort.','bodyZh':'献给橙色军团的致敬。明亮的橙色、白色线条与融入涂装的车迷影像，记录 2024 年赞德沃特的主场气氛。','source':'https://news.verstappen.com/en/gallerydetail/584/'}]
for e in editions:
 other=editions[1] if e is editions[0] else editions[0];directory=PUBLIC/'helmets'/e['id'];directory.mkdir(parents=True,exist_ok=True)
 e['materials']='/helmet-materials.js?v='+hashlib.sha256((PUBLIC/'helmet-materials.js').read_bytes()).hexdigest()[:12]
 e['model']='/gl/models/'+e['id']+'.glb?v='+hashlib.sha256((PUBLIC/'gl/models'/(e['id']+'.glb')).read_bytes()).hexdigest()[:12]
 config=json.dumps(e,ensure_ascii=False).replace('<','\\u003c')
 csshash=hashlib.sha256((PUBLIC/'helmet-page.css').read_bytes()).hexdigest()[:10];jshash=hashlib.sha256((PUBLIC/'helmet-page.js').read_bytes()).hexdigest()[:10]
 gallery=''.join(f'<figure><a href="{photo}" target="_blank" aria-label="查看原图 / View original"><img src="{photo}" alt="{e["name"]} · view {i+1:02d}" loading="lazy"></a><figcaption>VIEW {i+1:02d} / {e["zh"]}</figcaption></figure>' for i,photo in enumerate(e['photos']))
 html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e['name']} — MV33 Helmet Archive</title><meta name="description" content="{e['zh']} / Max Verstappen helmet archive"><link rel="icon" id="mv-favicon" type="image/svg+xml" href="/max/favicon-light.svg"><link rel="stylesheet" href="/helmet-page.css?v={csshash}"><script type="importmap">{{"imports":{{"three":"/vendor/three/three.module.js"}}}}</script></head>
<body><header class="edition-nav"><a class="edition-brand" href="/" aria-label="MV33 首页"><img src="/max/mv-orange.svg" alt="MV"><span>MAX<br>VERSTAPPEN</span></a><nav aria-label="头盔版本 / Helmet editions">{''.join(f'<a href="/helmets/{x["id"]}/" '+('aria-current="page" ' if x is e else '')+f'>{x["name"]}</a>' for x in editions)}</nav><a class="home-link" href="/">HOME ↗</a></header>
<main><section class="edition-hero" aria-labelledby="edition-title"><div class="edition-title"><p class="eyebrow">{e['eyebrow']}</p><h1 id="edition-title">{e['title']}</h1><p class="edition-zh">{e['zh']}</p></div><span class="edition-year" aria-hidden="true">{e['year']}</span><div class="model-stage"><img class="model-fallback" src="{e['poster']}" alt="{e['zh']} 正面摄影"><canvas id="helmet-canvas" tabindex="0" aria-label="可交互三维头盔。拖动旋转，方向键转动，Home 恢复正面。"></canvas><p id="model-status" role="status">LOADING HELMET / 正在加载头盔</p></div><div class="model-controls" aria-label="三维视角"><div class="view-controls"><button data-view="front" aria-pressed="true">FRONT</button><button data-view="left" aria-pressed="false">LEFT</button><button data-view="right" aria-pressed="false">RIGHT</button><button data-view="back" aria-pressed="false">BACK</button></div><button id="wireframe" aria-pressed="false">WIREFRAME / 线框</button></div><p class="interaction-hint">DRAG TO ROTATE · SCROLL TO ZOOM<span>拖动旋转 · 滚轮缩放</span></p><a class="hero-scroll" href="#details">EXPLORE THE DETAILS ↓</a></section>
<section class="edition-story" id="details"><p class="eyebrow">THE DETAILS / 设计细节</p><h2>{e['story']}</h2><div class="story-copy"><p>{e['body']}</p><p lang="zh-CN">{e['bodyZh']}</p><p class="model-note">三维展示由独立创作者网格结合多视角摄影重建，局部涂装与真实头盔可能有差异。下方保留原始摄影供对照。</p></div></section><section class="edition-gallery" aria-label="官方多角度摄影">{gallery}</section>
<footer class="edition-footer"><a class="next-edition" href="/helmets/{other['id']}/"><span>NEXT HELMET / 下一款</span><strong>{other['name']} ↗</strong></a><div class="credits"><p>“<a href="https://skfb.ly/pEDBZ" target="_blank" rel="noopener">Helmet Redbull - Max Verstappen</a>” by <a href="https://sketchfab.com/Fabianmml" target="_blank" rel="noopener">Maubian</a> / <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. Adapted: scale, web textures and edition livery reconstruction.</p><p>Photography: Verstappen.com / David Klopman; 2023 product photography via Red Bull Shop. <a href="{e['source']}" target="_blank" rel="noopener">Photo source ↗</a></p><p>MV33 — An unofficial, non-commercial fan study. <a href="/assets.html">Asset library ↗</a></p></div></footer></main><script type="application/json" id="helmet-edition">{config}</script><script type="module" src="/helmet-page.js?v={jshash}"></script></body></html>'''
 (directory/'index.html').write_text(html)
print('Built two helmet edition routes')
